'use strict'
// Runs the bundle generated by Rust (SIGNET_BUNDLE_DIR, set by tests/js_tests.rs) in a fake page, like signet-web will.
const test = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const vm = require('node:vm')
const { makeWindow } = require('./fakedom')

const dir = process.env.SIGNET_BUNDLE_DIR
const skip = dir ? false : 'SIGNET_BUNDLE_DIR not set (run through cargo test)'

function run(file, href, main = true, extra = {}) {
  const w = makeWindow({ href, main })
  Object.assign(w.g, extra)
  const posted = []
  w.g[ '__signetPost' ] = (channel, json) => posted.push([channel, JSON.parse(json)])
  w.g.crypto = globalThis.crypto
  w.g.clearTimeout = () => {}
  const ctx = vm.createContext(w.g)
  vm.runInContext('globalThis.top = globalThis', ctx)
  vm.runInContext(fs.readFileSync(path.join(dir, file), 'utf8'), ctx, { filename: file })
  return { w, posted, ctx }
}

test('web page bundle installs the bridge and every script of the main frame', { skip }, () => {
  const { w, ctx } = run('web-main.js', 'https://example.com/')
  assert.equal(typeof w.g.__signetDispatch, 'function')
  assert.equal(w.g.__signetPost, undefined)
  assert.equal(typeof w.g.chrome.loadTimes, 'function')
  assert.ok(w.listeners.wheel, 'swipe')
  assert.ok(w.listeners.submit, 'swipe form submit')
  assert.ok(w.doc.listeners.focusin.length >= 2, 'passwords and autofill')
  // The dispatch function is not writable.
  assert.throws(() => vm.runInContext("'use strict'; globalThis.__signetDispatch = 1", ctx), (e) => e.name === 'TypeError')
})

test('the same bundle in a subframe only runs the all-frames scripts', { skip }, () => {
  const { w } = run('web-sub.js', 'https://example.com/', false)
  assert.equal(typeof w.g.chrome.csi, 'function')
  assert.equal(w.listeners.wheel, undefined)
  assert.equal(w.doc.listeners.focusin, undefined)
})

test('a swipe in the bundle reaches the post function and the reply comes back through dispatch', { skip }, () => {
  const { w, posted } = run('web-main.js', 'https://example.com/')
  for (let i = 0; i < 3; i++) {
    w.clock.now += 16
    w.fire('wheel', { isTrusted: true, ctrlKey: false, defaultPrevented: false, deltaX: -30, deltaY: 0, composedPath: () => [], target: w.doc.body })
  }
  const req = posted.find((p) => p[0] === 'swipe:can')
  assert.ok(req && typeof req[1].rid === 'string')
  w.g.__signetDispatch('reply', JSON.stringify({ rid: req[1].rid, ok: true, data: { enabled: true, back: true, forward: true } }))
  for (let i = 0; i < 14; i++) {
    w.clock.now += 16
    w.fire('wheel', { isTrusted: true, ctrlKey: false, defaultPrevented: false, deltaX: -30, deltaY: 0, composedPath: () => [], target: w.doc.body })
  }
  assert.deepEqual(posted.filter((p) => p[0] === 'swipe:navigate').map((p) => p[1].data), ['back'])
})

test('notes bundle defines the notes objects on a document route', { skip }, () => {
  const { w } = run('notes.js', 'signet://note/0b9d0f3e-1c1a-4a53-9a6f-2f6d2b1c9e11')
  assert.equal(typeof w.g.signetNotes.load, 'function')
  assert.equal(typeof w.g.signet.getLocale, 'function')
})

test('gpc and everything bundles run without throwing', { skip }, () => {
  class Navigator {}
  const { w } = run('gpc.js', 'https://example.com/', true, { Navigator })
  assert.equal(new Navigator().globalPrivacyControl, true)
  assert.equal(typeof w.g.__signetDispatch, 'function')
  // Passkey interception needs a credentials container; without one it does nothing.
  const all = run('everything.js', 'https://example.com/', true, { Navigator: class Navigator {} })
  assert.equal(typeof all.w.g.chrome.csi, 'function')
})
